const r = $input.first().json || {};
const SEM = { encontrou: false, orientacao: 'Sem informação segura. Não afirme nada sobre o assunto: diga que vai confirmar e use chamar_dono (gravidade baixa).' };
if (r.error || r.ok === false) return [{ json: { ...SEM, erro: 'indisponivel' } }];
const brutos = Array.isArray(r.trechos) ? r.trechos : [];
let trechos = brutos.slice(0, 3).map((t) => ({ titulo: String(t.titulo || '').slice(0, 80), resposta: String(t.resposta_pronta || '').slice(0, 700), proximo_passo: String(t.proximo_passo || '').slice(0, 200) }));
if (r.resposta_direta) trechos = [{ titulo: String((brutos[0] && brutos[0].titulo) || '').slice(0, 80), resposta: String(r.resposta_direta).slice(0, 700), proximo_passo: String((brutos[0] && brutos[0].proximo_passo) || '').slice(0, 200) }];
trechos = trechos.filter((t) => t.resposta).map((t) => (t.proximo_passo ? t : { titulo: t.titulo, resposta: t.resposta }));
if (!r.encontrou || !trechos.length) return [{ json: SEM }];
return [{ json: { encontrou: true, trechos } }];
